177	export function formatRelativeDate(dateStr: string): string {
178	  const now = new Date();
179	  const date = new Date(dateStr);
180	  const diffMs = now.getTime() - date.getTime();
181	  const diffMins = Math.floor(diffMs / 60000);
182	  const diffHours = Math.floor(diffMs / 3600000);
183	  const diffDays = Math.floor(diffMs / 86400000);
184	
185	  if (diffMins < 1) return "Just now";
186	  if (diffMins < 60) return `${diffMins}m ago`;
187	  if (diffHours < 24) return `${diffHours}h ago`;
188	  if (diffDays < 7) return `${diffDays}d ago`;
189	  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
190	}
