104	function CopyButton({ text }: { text: string }) {
105	  const [copied, setCopied] = useState(false);
106	
107	  const handleCopy = async () => {
108	    try {
109	      await navigator.clipboard.writeText(text);
110	      setCopied(true);
111	      setTimeout(() => setCopied(false), 2000);
112	    } catch {
113	      const textarea = document.createElement("textarea");
114	      textarea.value = text;
115	      document.body.appendChild(textarea);
116	      textarea.select();
117	      document.execCommand("copy");
118	      document.body.removeChild(textarea);
119	      setCopied(true);
120	      setTimeout(() => setCopied(false), 2000);
121	    }
122	  };
123	
124	  return (
125	    <TooltipProvider delayDuration={200}>
126	      <Tooltip>
127	        <TooltipTrigger asChild>
128	          <button
129	            onClick={handleCopy}
130	            className={cn(
131	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
132	              copied
133	                ? "bg-green-50 text-green-600 border border-green-200"
134	                : "bg-white/80 text-slate-500 border border-slate-200 hover:bg-slate-50 hover:text-slate-700"
135	            )}
136	          >
137	            {copied ? (
138	              <><Check className="h-3 w-3" />Copied</>
139	            ) : (
140	              <><Copy className="h-3 w-3" />Copy</>
141	            )}
142	          </button>
143	        </TooltipTrigger>
144	        <TooltipContent side="top">
145	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
146	        </TooltipContent>
147	      </Tooltip>
148	    </TooltipProvider>
149	  );
150	}
