77	serve(async (req: Request) => {
78	  // Preflight
79	  if (req.method === "OPTIONS") {
80	    return new Response("ok", { headers: corsHeaders });
81	  }
82	
83	  if (req.method !== "POST") {
84	    return corsResponse({ error: "Method not allowed" }, 405);
85	  }
86	
87	  // ── 1. Auth ─────────────────────────────────────────────────
88	  const authHeader = req.headers.get("Authorization");
89	  if (!authHeader?.startsWith("Bearer ")) {
90	    return corsResponse({ error: "Missing authorization header" }, 401);
91	  }
92	  const token = authHeader.replace("Bearer ", "").trim();
93	
94	  const supabase = createClient(
95	    Deno.env.get("SUPABASE_URL") ?? "",
96	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
97	  );
98	
99	  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
100	  if (!user || authError) {
101	    return corsResponse({ error: "Unauthorized" }, 401);
102	  }
103	
104	  // ── 2. Parse request body ────────────────────────────────────
105	  let url: string;
106	  let pageType: PageType;
107	  try {
108	    const body = await req.json();
109	    url = body.url;
110	    pageType = body.page_type ?? "other";
111	    if (!url || typeof url !== "string") {
112	      return corsResponse({ error: "url is required" }, 400);
113	    }
114	    // Normalize URL
115	    if (!url.startsWith("http://") && !url.startsWith("https://")) {
116	      url = `https://${url}`;
117	    }
118	    new URL(url); // validate format — throws if invalid
119	  } catch (_e) {
120	    return corsResponse({ error: "Invalid request body or URL" }, 400);

120	    return corsResponse({ error: "Invalid request body or URL" }, 400);
121	  }
122	
123	  // ── 3. Check scan limit ──────────────────────────────────────
124	  const { data: allowed, error: limitError } = await supabase.rpc(
125	    "increment_scan_usage",
126	    { user_uuid: user.id },
127	  );
128	  if (limitError || !allowed) {
129	    return corsResponse(
130	      { error: "Scan limit reached. Upgrade your plan to continue." },
131	      429,
132	    );
133	  }
134	
135	  // ── 4. Create scan record ────────────────────────────────────
136	  const { data: scan, error: scanInsertError } = await supabase
137	    .from("scans")
