143	      device: "both",
144	    })
145	    .select("id")
146	    .single();
147	
148	  if (scanInsertError || !scan) {
149	    console.error("Failed to create scan record:", scanInsertError);
150	    return corsResponse({ error: "Failed to initiate scan" }, 500);
151	  }
152	
153	  const scanId: string = scan.id;
154	
155	  // All subsequent errors must update scan status to failed
156	  const failScan = async (message: string) => {
157	    await supabase
158	      .from("scans")
159	      .update({ status: "failed", error_message: message })
160	      .eq("id", scanId);
161	  };
162	
163	  try {
164	    // ── 5. Screenshot + Scrape ─────────────────────────────────
165	    let screenshotData: ScreenshotServiceResponse;
166	    try {
167	      screenshotData = await captureScreenshot(url);
168	    } catch (e) {
169	      const msg = e instanceof Error ? e.message : "Screenshot capture failed";
170	      await failScan(msg);
171	      return corsResponse({ error: msg }, 500);
172	    }
173	
174	    // ── 6. Upload screenshot ───────────────────────────────────
175	    let screenshotUrl: string | null = null;
176	    if (screenshotData.screenshot_base64) {
177	      try {
178	        screenshotUrl = await uploadScreenshot(
179	          supabase,
180	          screenshotData.screenshot_base64,
181	          scanId,
182	        );
183	      } catch (e) {
184	        // Non-fatal — scan continues without screenshot
185	        console.warn("Screenshot upload failed:", e);
186	      }
187	    }
188	
189	    // Update scan with page metadata from screenshot service
190	    await supabase
191	      .from("scans")
192	      .update({
193	        page_title: screenshotData.page_title || null,
194	        favicon_url: screenshotData.favicon_url || null,
195	        screenshot_url: screenshotUrl,
196	      })
197	      .eq("id", scanId);
198	
199	    // ── 7. AI Vision Analysis ──────────────────────────────────
200	    let visionResult: VisionAnalysisResult;
201	    try {
202	      visionResult = await runVisionAnalysis(
203	        screenshotData.screenshot_base64,
204	        pageType,
205	      );
206	    } catch (e) {
207	      const msg = e instanceof Error ? e.message : "AI vision analysis failed";
208	      await failScan(msg);
209	      return corsResponse({ error: msg }, 500);
210	    }
211	
212	    // ── 8. AI Text Analysis ────────────────────────────────────
213	    let textResult: TextAnalysisResult;
214	    try {
215	      textResult = await runTextAnalysis(screenshotData.dom_data, pageType);
216	    } catch (e) {
217	      const msg = e instanceof Error ? e.message : "AI text analysis failed";
218	      await failScan(msg);
219	      return corsResponse({ error: msg }, 500);
220	    }
221	
222	    // ── 9. PageSpeed Analysis ──────────────────────────────────
223	    let pageSpeedResult: PageSpeedResult;
224	    try {
225	      pageSpeedResult = await runPageSpeedAnalysis(url);
226	    } catch (e) {
227	      // Non-fatal — use fallback score
228	      console.warn("PageSpeed analysis failed, using fallback:", e);
