248	      findings: pr.findings,
249	    }));
250	
251	    const { error: resultsError } = await supabase
252	      .from("scan_results")
253	      .insert(scanResultRows);
254	
255	    if (resultsError) {
256	      console.error("Failed to insert scan_results:", resultsError);
257	      await failScan("Failed to save analysis results");
258	      return corsResponse({ error: "Failed to save results" }, 500);
259	    }
260	
261	    // Update scan to completed
262	    const { error: updateError } = await supabase
263	      .from("scans")
264	      .update({
