291	async function captureScreenshot(url: string): Promise<ScreenshotServiceResponse> {
292	  const serviceUrl = Deno.env.get("SCREENSHOT_SERVICE_URL");
293	
294	  if (serviceUrl) {
295	    // Production: Railway Puppeteer service
296	    const apiKey = Deno.env.get("SCREENSHOT_SERVICE_API_KEY") ?? "";
297	    const res = await fetch(`${serviceUrl}/screenshot`, {
298	      method: "POST",
299	      headers: {
300	        "Content-Type": "application/json",
301	        "X-API-Key": apiKey,
302	      },
303	      body: JSON.stringify({ url, device: "desktop" }),
304	    });
305	
306	    if (!res.ok) {
307	      const text = await res.text();
308	      throw new Error(`Screenshot service error ${res.status}: ${text.slice(0, 200)}`);
309	    }
310	
311	    return await res.json() as ScreenshotServiceResponse;
312	  }
313	
314	  // Dev fallback: ScreenshotOne API + fetch DOM ourselves
315	  console.warn(
316	    "SCREENSHOT_SERVICE_URL not set — using dev fallback (ScreenshotOne + fetch).",
317	  );
318	  return await devFallbackCapture(url);
319	}

