/**
 * send-email — Edge Function
 *
 * Sends transactional emails via Resend (HTTP, no SDK — Deno compatible).
 *
 * Accepted request body shapes:
 *   { type: 'welcome';        to: string; data: { name: string } }
 *   { type: 'scan_complete';  to: string; data: { name: string; url: string; score: number; scan_id: string; critical_count: number; quick_wins: number } }
 *   { type: 'weekly_digest';  to: string; data: { name: string; scans_this_week: number; avg_score: number } }
 *
 * Required env vars:
 *   RESEND_API_KEY — Resend secret key
 *   APP_URL        — e.g. https://app.convertscan.com (no trailing slash)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

// ── CORS ──────────────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── Brand constants ───────────────────────────────────────────────

const BRAND_COLOR = "#6366F1"; // indigo-500
const BRAND_NAME = "ConvertScan";
const FROM_ADDRESS = `${BRAND_NAME} <noreply@convertscan.com>`;

// ── Shared email layout helpers ───────────────────────────────────

function emailWrapper(content: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${BRAND_NAME}</title>
</head>
<body style="margin:0;padding:0;background:#F8FAFC;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#F8FAFC;padding:32px 16px;">
    <tr>
      <td align="center">
        <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">

          <!-- Header -->
          <tr>
            <td style="background:${BRAND_COLOR};border-radius:12px 12px 0 0;padding:24px 32px;">
              <p style="margin:0;font-size:20px;font-weight:700;color:#FFFFFF;letter-spacing:-0.3px;">${BRAND_NAME}</p>
              <p style="margin:4px 0 0;font-size:11px;color:rgba(255,255,255,0.7);letter-spacing:0.5px;text-transform:uppercase;">CRO Audit Platform</p>
            </td>
          </tr>

          <!-- Body -->
          <tr>
            <td style="background:#FFFFFF;padding:36px 32px;border-left:1px solid #E2E8F0;border-right:1px solid #E2E8F0;">
              ${content}
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="background:#F1F5F9;border-radius:0 0 12px 12px;border:1px solid #E2E8F0;border-top:0;padding:20px 32px;">
              <p style="margin:0;font-size:12px;color:#94A3B8;line-height:1.6;">
                You received this email because you have an account at ${BRAND_NAME}.
                <br />
                &copy; ${new Date().getFullYear()} ${BRAND_NAME}. All rights reserved.
                <br />
                <a href="{{UNSUBSCRIBE_URL}}" style="color:#6366F1;text-decoration:none;">Unsubscribe</a> &nbsp;·&nbsp;
                <a href="https://convertscan.com/privacy" style="color:#6366F1;text-decoration:none;">Privacy Policy</a>
              </p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

function ctaButton(label: string, href: string): string {
  return `<table cellpadding="0" cellspacing="0" style="margin:28px 0;">
    <tr>
      <td style="background:${BRAND_COLOR};border-radius:8px;">
        <a href="${href}"
           style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#FFFFFF;text-decoration:none;letter-spacing:-0.1px;">
          ${label}
        </a>
      </td>
    </tr>
  </table>`;
}

function scoreChip(score: number): string {
  const color = score >= 70 ? "#22C55E" : score >= 40 ? "#F59E0B" : "#EF4444";
  const label = score >= 85 ? "Excellent" : score >= 70 ? "Good" : score >= 55 ? "Average" : score >= 40 ? "Below Average" : "Poor";
  return `<span style="display:inline-block;background:${color};color:#fff;font-size:22px;font-weight:700;padding:8px 18px;border-radius:10px;letter-spacing:-0.5px;">
    ${score}<span style="font-size:13px;opacity:0.85;">/100</span>
  </span>
  <span style="display:inline-block;background:${color}18;color:${color};font-size:13px;font-weight:600;padding:6px 12px;border-radius:6px;margin-left:10px;vertical-align:middle;">
    ${label}
